+/// What a running tool call shows while its input streams in: for a tool of a
+/// known kind, what it is getting ready to do, as tall as the raw output it
+/// replaces so the row keeps its height; for any other, the raw output.
+fn tool_input_pending(call: &ToolCall, reply: &Reply, cx: &App) -> AnyElement {
+    let Some(label) = ToolKind::of(&call.name).pending_input() else {
+        return raw_tail(reply, cx);
+    };
+    let theme = cx.theme();
+    v_flex()
+        .w_full()
+        .min_w_0()
+        .gap_1()
+        .child(div().text_color(theme.muted_foreground).child(label))
+        .child(Skeleton::new().w(relative(0.6)).h_4().rounded_md())
+        .into_any_element()
