/// Default px(12) to match a dock tab bar's px_3
fn inner_paddings(&self, size: Size) -> Edges<Pixels> {
    let mut padding_x = match size {
        Size::XSmall => px(8.),
        Size::Small => px(10.),
        Size::Large => px(16.),
        _ => px(12.),
    };

    if matches!(self, TabVariant::Underline) {
        padding_x = px(0.);
    }

    Edges {
        left: padding_x,
        right: padding_x,
        ..Default::default()
    }
}

fn inner_margins(&self, size: Size) -> Edges<Pixels> {
    match size {
        Size::XSmall => match self {
            TabVariant::Underline => Edges {
                top: px(1.),
                bottom: px(2.),
                ..Default::default()
            },
            _ => Edges::all(px(0.)),
        },
        Size::Small => match self {
            TabVariant::Underline => Edges {
                top: px(2.),
                bottom: px(3.),
                ..Default::default()
            },
            _ => Edges::all(px(0.)),
        },
        Size::Large => match self {
            TabVariant::Underline => Edges {
                top: px(5.),
                bottom: px(6.),
                ..Default::default()
            },
            _ => Edges::all(px(0.)),
        },
        _ => match self {
            TabVariant::Underline => Edges {
                top: px(3.),
                bottom: px(4.),
                ..Default::default()
            },
            _ => Edges::all(px(0.)),
        },
    }
}

